class GreedyPolicy():
    def __init__(self,
                 environment_info: MDPInfo,
                 obsprocessors: Optional[List[object]] = None,
                 actionprocessors: Optional[List[object]] = None,
                 agent_name: str | None = None,
                 ex_prices: np.ndarray | None = None,
                 alpha: np.ndarray | None = None,
                 beta: np.ndarray | None = None,
                 price_function = None,
                 g = None,
                 ):
        assert type(alpha) == type(beta), "alpha and beta must be of the same type"
        if type(alpha) == None:
            alpha = np.zeros(environment_info.observation_space.shape[1])   
            beta = np.zeros(environment_info.observation_space.shape[1])
        assert ex_prices.shape[0] >= 2
        self.environment_info = environment_info
        self.ex_prices = ex_prices
        self.alpha = alpha
        self.beta = beta
        self.actionprocessors = actionprocessors
        self.price_function = price_function # Needs to return an np array
        self.g = g
        self.t = 0
        self.X = np.empty((0, environment_info.observation_space.shape[1] * 2)) 
        self.Y = np.empty((0, 1))
        self.mode = "train"

    def draw_action(self, observation: np.ndarray):
        if self.t < self.ex_prices.shape[0]:
            prices = self.ex_prices[self.t]
        else:
            prices = np.empty(0)
            for x in observation:
                price = self.price_function(x, self.alpha, self.beta)
                prices = np.append(prices, price)
            
        for processor in self.actionprocessors:
            prices = processor(prices)
        
        return prices
    
    def fit(self, X, Y, action):
        assert self.mode == "train"
        self.t += 1
        X = np.concat([X, X * action])
        self.X = np.vstack([self.X, X])
        self.Y = np.vstack([self.Y, Y])
        self.parameter_update()
    
    def parameter_update(self):
        model = sm.OLS(self.Y, self.X)
        results = model.fit()
        self.alpha = results.params[:self.environment_info.observation_space.shape[1]]
        self.beta = results.params[self.environment_info.observation_space.shape[1]:]
        
    def reset(self):
        return

